CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,name text NOT NULL DEFAULT '',role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','creator','superadmin')),verified_at timestamptz,disabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_tokens(hash text PRIMARY KEY,email text NOT NULL,expires_at timestamptz NOT NULL,return_path text NOT NULL DEFAULT '/dashboard');
CREATE TABLE sessions(hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE rate_limits(key text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE uploads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),object_key text UNIQUE NOT NULL,kind text NOT NULL CHECK(kind IN ('preview','package')),size integer NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),slug text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL,category text NOT NULL,mode text NOT NULL CHECK(mode IN ('free','donation','paid')),price integer NOT NULL CHECK(price BETWEEN 0 AND 100000000),preview_key text,package_key text,compatibility text NOT NULL DEFAULT 'Windows 10 / 11',formats text NOT NULL DEFAULT '.cur / .ani',states integer NOT NULL DEFAULT 15 CHECK(states BETWEEN 1 AND 100),version text NOT NULL DEFAULT '1.0',license text NOT NULL DEFAULT 'Personal use only. Redistribution is not permitted.',published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((mode='free' AND price=0) OR (mode<>'free' AND price>=1000)));
CREATE TABLE payment_settings(id integer PRIMARY KEY CHECK(id=1),server_key text NOT NULL,production boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),product_id uuid NOT NULL REFERENCES products(id),creator_id uuid NOT NULL REFERENCES users(id),amount integer NOT NULL CHECK(amount>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded','review')),request_key uuid NOT NULL,payment_key text,production boolean NOT NULL DEFAULT false,checkout_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_key));
CREATE TABLE entitlements(user_id uuid NOT NULL REFERENCES users(id),product_id uuid NOT NULL REFERENCES products(id),order_id uuid NOT NULL REFERENCES orders(id),active boolean NOT NULL DEFAULT true,acquired_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
CREATE TABLE payment_events(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),status text NOT NULL,event_hash text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_views(product_id uuid NOT NULL REFERENCES products(id),visitor_hash text NOT NULL,day date NOT NULL DEFAULT CURRENT_DATE,PRIMARY KEY(product_id,visitor_hash,day));
CREATE TABLE audit_log(id bigserial PRIMARY KEY,actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,target text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_creator_date ON orders(creator_id,created_at);
CREATE INDEX products_published ON products(published,created_at);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX tokens_expiry ON login_tokens(expires_at);
